def transform(grid):
    out = [row[:] for row in grid]
    red = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    start, end = sorted(red)
    targets = []
    for r, row in enumerate(grid):
        counts = {}
        for v in row:
            counts[v] = counts.get(v, 0) + 1
        bg = max(counts, key=counts.get)
        special = [c for c, v in enumerate(row) if v != bg]
        if special and len(special) < len(row) // 2:
            targets.append((r, special[len(special) // 2]))
    r, c = start
    for tr, tc in targets + [end]:
        if r != tr:
            stop = tr if (tr, tc) == end else tr - (1 if tr > r else -1)
            step = 1 if stop > r else -1
            for rr in range(r, stop + (1 if step == 1 else -1), step):
                if rr != tr:
                    out[rr][c] = 2
            r = stop
        step = 1 if tc > c else -1
        for cc in range(c, tc + step, step):
            out[r][cc] = 2
        c = tc
        if (tr, tc) != end:
            out[tr][tc] = 2
            r = tr
    return out
